chapter(24, 'Closing: shortcuts, help, quick-reference', 'Learn the function keys and the shortcut list, use search once more, open your own menu for help and sign-out, and keep the quick-reference card.',
        'Aarav (Reception)', 'reception', menu='Modules Home')
step('You are Aarav on Modules Home again. The last chapter is about speed: keys that take you straight to the screens you use all day.', 'A receptionist who knows the keys serves the next guest sooner.', target='sel:.fit-home-grid', auto=['key:Escape', 'user:reception'], action='read', expect='Modules Home for Aarav.', check="ctx.uid==='reception'")
press('alt+/', 'Press Alt and the slash key to open the list of keyboard shortcuts.', 'The list always shows the keys your role may use.', target='dialog:', expect='The Keyboard shortcuts dialog opens.', check="!!q('[role=dialog]')")
read('The list shows the keys: F2 New booking, F3 Arrivals & check-in, F4 In-house stays, F6 Room board, F7 Guests & folios, F8 Check-out, F9 Rate / guest change, F10 Cashier shift, Alt+B Counter bill and Alt+/ this list. A key only works when you may use that screen and no dialog is open.', 'Keys that you may not use are not listed for you.', target='dialog:', expect='The list of shortcuts.')
press('Escape', 'Press Escape to close the list.', 'Escape closes every dialog.', target='sel:.fit-home-grid', expect='Modules Home is shown.', check="!q('[role=dialog]')")
press('F6', 'Press F6.', 'F6 goes to the Room board from any screen.', target='sel:main h1', expect='The Room board opens.', check="ctx.page==='rooms'")
press('F3', 'Press F3.', 'F3 goes to Arrivals & check-in.', target='sel:main h1', expect='The Arrivals & check-in page opens.', check="ctx.page==='arrivals'")
press('ctrl+k', 'Press Control and K to search from anywhere. Search is the other way to jump: type a part of a page name.', 'Together, the keys and the search take you to any screen within two keystrokes.', target='sel:.search-box', expect='The search box opens.', check="!!q('.search-box')")
press('Escape', 'Press Escape.', 'Nothing is lost by closing the search.', target='sel:main h1', expect='The search box is closed.', check="!q('.search-box')")
click('sel:.current-user-btn', 'Click your own name at the top right: Aarav, Reception.', 'This is your own menu: change my password or PIN, display mode, sign out and about this build.', expect='Your profile menu opens.', check="!!q('[role=dialog]')")
read('The menu lets you change your own PIN, pick the display mode Auto, Desktop or Mobile for this device, see the build information and Sign out. Always sign out when you leave the desk, so nobody works under your name.', 'Everything done in HCC is recorded under the name of the signed-in person.', target='dialog:', expect='The profile menu.')
read('Quick reference. Modules Home: pick a module. Ctrl K: search. F2 new booking, F3 arrivals, F4 in-house, F6 room board, F7 folios, F8 check-out, F10 cashier. Esc closes a dialog. Ask the Manager for approvals, the Owner for credit notes and credit limits. Nothing in the demo is real money or a real guest.', 'Keep this card at the desk; the role cards of the training give the same facts for every role.', target='dialog:', expect='The quick reference.')
